import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
def preferences_for(ctx):
    weights = torch.tensor([1.0 + int(ctx.index) % 3, 1.0 + (int(ctx.index) + 1) % 3])
    return weights / weights.sum()
@synth.generator
def vector_samples(ctx):
    inputs = torch.randn(4, generator=ctx.rng.torch)
    target_velocity = torch.randn(2, generator=ctx.rng.torch)
    return {"inputs": synth.Tensor(inputs), "target_velocity": synth.Tensor(target_velocity), "preferences": synth.Tensor(preferences_for(ctx))}
@synth.generator
def grid_samples(ctx):
    inputs = torch.randn(4, generator=ctx.rng.torch)
    target_velocity = torch.randn(2, 2, generator=ctx.rng.torch)
    return {"inputs": synth.Tensor(inputs), "target_velocity": synth.Tensor(target_velocity), "preferences": synth.Tensor(preferences_for(ctx))}
class VelocityModel(nn.Module):
    def __init__(self, velocity_shape):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=2 if len(velocity_shape) == 1 else 4)
        self.velocity_shape = velocity_shape
    def forward(self, inputs):
        return {"velocity": self.network(inputs).reshape(inputs.shape[0], *self.velocity_shape)}
def train(name, generator, velocity_shape, margin):
    dataset = synth.Spec(name, generator=generator, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
    training_data = dataset.for_recipe("structured-objective", split="train")
    trainer = Trainer(VelocityModel(velocity_shape), training_data, recipe="structured-objective", recipe_config={"loss": "fp2-triplet-velocity", "loss_kwargs": {"margin": margin}, "bindings": {"logits_or_prediction": {"output": "velocity"}, "targets": {"batch": "target_velocity"}, "preferences": {"batch": "preferences"}}}, batch_size=4, max_epochs=1, device="cpu", logger="none", monitor="none")
    trainer.fit()
train("fp2-vector-velocity", vector_samples, (2,), 1.0)
train("fp2-grid-velocity", grid_samples, (2, 2), 0.5)
